def fizz_buzz(n):
  result = []
  for i in range(1, n + 1):
    if i % 15 == 0:
      result.append('FizzBuzz')
    elif i % 3 == 0:
      result.append('Fizz')
    elif i % 5 == 0:
      result.append('Buzz')
    else:
      result.append(str(i))
  return result

def two_sum(nums, target):
  seen = {}
  for i, num in enumerate(nums):
    complement = target - num
    if complement in seen:
      return [seen[complement], i]
    seen[num] = i
  return []

def contains_duplicate(nums):
  seen = set()
  for num in nums:
    if num in seen:
      return True
    seen.add(num)
  return False

def length_of_last_word(text):
  length = 0
  for i in range(len(text) - 1, -1, -1):
    if text[i] != ' ':
      length += 1
    elif length > 0:
      return length
  return length

def is_valid_brackets(s):
  stack = []
  bracket_map = {')': '(', '}': '{', ']': '['}
  for char in s:
    if char not in bracket_map:
      stack.append(char)
    else:
      top_element = stack.pop() if stack else '#'
      if bracket_map[char] != top_element:
        return False
  return not stack

def search_insert(nums, target):
  left = 0
  right = len(nums) - 1
  while left <= right:
    mid = (left + right) // 2
    if nums[mid] == target:
      return mid
    elif nums[mid] < target:
      left = mid + 1
    else:
      right = mid - 1
  return left

def plus_one(digits):
