    if digits[i] == 9:
      digits[i] = 0
    else:
      digits[i] += 1
      return digits
  return [1] + digits

def majority_element(nums):
  count = 0
  candidate = None
  for num in nums:
    if count == 0:
      candidate = num
    if num == candidate:
      count += 1
    else:
      count -= 1
  return candidate

