def find_difference(s, t):
  result = 0
  for char in s:
    result ^= ord(char)
  for char in t:
    result ^= ord(char)
  return chr(result)

def is_isomorphic(s, t):
  if len(s) != len(t):
    return False
  map_s_to_t = {}
  map_t_to_s = {}
  for char_s, char_t in zip(s, t):
    if char_s in map_s_to_t and map_s_to_t[char_s] != char_t:
      return False
    if char_t in map_t_to_s and map_t_to_s[char_t] != char_s:
      return False
    map_s_to_t[char_s] = char_t
    map_t_to_s[char_t] = char_s
  return True

def longest_common_prefix(strs):
  if not strs:
    return ""
  prefix = strs[0]
  for s in strs[1:]:
    while not s.startswith(prefix):
      prefix = prefix[:-1]
      if not prefix:
        return ""
  return prefix

def generate_pascals(numRows):
  if numRows == 0:
    return []
  triangle = [[1]]
  for i in range(1, numRows):
    prev_row = triangle[-1]
    new_row = [1]
    for j in range(1, i):
      new_row.append(prev_row[j - 1] + prev_row[j])
    new_row.append(1)
    triangle.append(new_row)
  return triangle

def is_perfect_square(num):
  left = 1
  right = num
  while left <= right:
    mid = (left + right) // 2
    squared = mid * mid
    if squared == num:
      return True
    elif squared < num:
      left = mid + 1
    else:
      right = mid - 1
  return False

def count_words(s):
  count = 0
  in_word = False
  for char in s:
    if char == ' ':
      in_word = False
    elif not in_word:
      in_word = True
      count += 1
  return count

def diagonal_sum(mat):
  n = len(mat)
  total = 0
  for i in range(n):
    total += mat[i][i]
    total += mat[i][n - 1 - i]
  if n % 2 != 0:
    total -= mat[n // 2][n // 2]
  return total

def find_minimum(nums):
  if not nums:
    return None
  min_val = nums[0]
  for num in nums:
    if num < min_val:
      min_val = num
  return min_val

def count_vowels(text):
  vowels = set('aeiouAEIOU')
  count = 0
  for char in text:
    if char in vowels:
      count += 1
  return count

def is_palindrome(s):
  left = 0
  right = len(s) - 1
  while left < right:
    if s[left] != s[right]:
      return False
    left += 1
    right -= 1
  return True

def sum_of_squares(n):
  total = 0
  for i in range(1, n + 1):
    total += i * i
  return total

def remove_duplicates(nums):
  if not nums:
    return 0
  write_index = 1
  for i in range(1, len(nums)):
    if nums[i] != nums[i - 1]:
      nums[write_index] = nums[i]
      write_index += 1
  return write_index

def is_sorted(arr):
  for i in range(1, len(arr)):
    if arr[i] < arr[i - 1]:
      return False
  return True

def intersection(nums1, nums2):
  set1 = set(nums1)
  result = []
  for num in nums2:
    if num in set1:
      result.append(num)
      set1.remove(num)
  return result

def factorial(n):
  if n < 0:
    return -1
  result = 1
  for i in range(2, n + 1):
    result *= i
  return result

def is_power_of_two(n):
  if n <= 0:
    return False
  while n % 2 == 0:
    n //= 2
  return n == 1

def first_unique_char(s):
  counts = {}
  for char in s:
    counts[char] = counts.get(char, 0) + 1
  for i in range(len(s)):
    if counts[s[i]] == 1:
      return i
  return -1

def is_anagram(s, t):
  if len(s) != len(t):
    return False
  counts = {}
  for char in s:
    counts[char] = counts.get(char, 0) + 1
  for char in t:
    if char not in counts or counts[char] == 0:
      return False
    counts[char] -= 1
  return True

def max_profit(prices):
  if not prices:
    return 0
  min_price = prices[0]
  max_profit = 0
  for price in prices:
    if price < min_price:
      min_price = price
    elif price - min_price > max_profit:
      max_profit = price - min_price
  return max_profit

def move_zeroes(nums):
  insert_pos = 0
  for num in nums:
    if num != 0:
      nums[insert_pos] = num
      insert_pos += 1
  while insert_pos < len(nums):
    nums[insert_pos] = 0
    insert_pos += 1
  return nums
